// Generated by exit-ramp. A Val Town std/sqlite-shaped facade over Cloudflare D1 (binding: DB).
//
// Matches: sqlite.execute(string | { sql, args }) and sqlite.batch([...]) with { columns, rows, rowsAffected, lastInsertRowid }.
// Differences: D1 is not libsql. Named parameters (:name, @name, $name) are rewritten to numbered ones here.
// Rows are plain objects (no array index access). lastInsertRowid is a number. batch() runs as one D1 transaction.
// Val Town "global" (account-wide) SQLite is not shared with other apps on Cloudflare: copy only this app's tables.
import { env } from "cloudflare:workers";

export type InValue = null | string | number | bigint | boolean | ArrayBuffer | Uint8Array | Date | undefined;
export type InArgs = InValue[] | Record<string, InValue>;
export type InStatement = string | { sql: string; args?: InArgs };

export interface ResultSet {
  columns: string[];
  columnTypes: string[];
  rows: Record<string, unknown>[];
  rowsAffected: number;
  lastInsertRowid: number | null;
}

/** Rewrite :name / @name / $name placeholders to ?N and return positional params. Skips strings and comments. */
export function toPositional(sql: string, args?: InArgs): { sql: string; params: unknown[] } {
  if (!args) return { sql, params: [] };
  if (Array.isArray(args)) return { sql, params: args.map(convert) };
  const order: string[] = [];
  let out = "";
  let i = 0;
  while (i < sql.length) {
    const c = sql[i];
    const n = sql[i + 1];
    if (c === "'" || c === '"' || c === "`") {
      let j = i + 1;
      while (j < sql.length && !(sql[j] === c && sql[j + 1] !== c)) j += sql[j] === c ? 2 : 1;
      out += sql.slice(i, j + 1);
      i = j + 1;
    } else if (c === "-" && n === "-") {
      const j = sql.indexOf("\n", i);
      const end = j === -1 ? sql.length : j;
      out += sql.slice(i, end);
      i = end;
    } else if (c === "/" && n === "*") {
      const j = sql.indexOf("*/", i + 2);
      const end = j === -1 ? sql.length : j + 2;
      out += sql.slice(i, end);
      i = end;
    } else if ((c === ":" || c === "@" || c === "$") && n !== undefined && /[A-Za-z_]/.test(n) && sql[i - 1] !== ":") {
      let j = i + 1;
      while (j < sql.length && /[A-Za-z0-9_]/.test(sql[j])) j++;
      const name = sql.slice(i + 1, j);
      let idx = order.indexOf(name);
      if (idx === -1) idx = order.push(name) - 1;
      out += "?" + (idx + 1);
      i = j;
    } else {
      out += c;
      i++;
    }
  }
  const missing = order.filter((name) => !(name in args));
  if (missing.length) throw new Error("Missing SQL parameter(s): " + missing.join(", "));
  return { sql: out, params: order.map((name) => convert((args as Record<string, InValue>)[name])) };
}

function convert(v: InValue): unknown {
  if (v === undefined) return null;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "bigint") return Number(v);
  if (v instanceof Date) return v.toISOString();
  if (v instanceof Uint8Array) return v.buffer.slice(v.byteOffset, v.byteOffset + v.byteLength);
  return v;
}

const isMulti = (sql: string) => sql.replace(/'(?:[^']|'')*'/g, "''").trim().replace(/;\s*$/, "").includes(";");
const isRead = (sql: string) => /^\s*(select|with|pragma|explain|values)\b/i.test(sql);

export class D1Sqlite {
  constructor(private readonly db: () => D1Database) {}

  private prepare(stmt: InStatement) {
    const { sql, args } = typeof stmt === "string" ? { sql: stmt, args: undefined } : stmt;
    const p = toPositional(sql, args);
    const prepared = this.db().prepare(p.sql);
    return { sql: p.sql, prepared: p.params.length ? prepared.bind(...p.params) : prepared };
  }

  private async shape(sql: string, prepared: D1PreparedStatement, result: D1Result<Record<string, unknown>>): Promise<ResultSet> {
    const rows = result.results ?? [];
    let columns = rows.length ? Object.keys(rows[0]) : [];
    if (!rows.length && isRead(sql)) {
      const raw = await prepared.raw<unknown[]>({ columnNames: true });
      columns = (raw[0] as string[] | undefined) ?? [];
    }
    return {
      columns,
      columnTypes: columns.map(() => ""),
      rows,
      rowsAffected: result.meta?.changes ?? 0,
      lastInsertRowid: isRead(sql) ? null : (result.meta?.last_row_id ?? null),
    };
  }

  async execute(stmt: InStatement): Promise<ResultSet> {
    const sqlText = typeof stmt === "string" ? stmt : stmt.sql;
    if (typeof stmt === "string" && isMulti(sqlText)) {
      await this.db().exec(sqlText);
      return { columns: [], columnTypes: [], rows: [], rowsAffected: 0, lastInsertRowid: null };
    }
    const { sql, prepared } = this.prepare(stmt);
    return this.shape(sql, prepared, await prepared.all<Record<string, unknown>>());
  }

  async batch(stmts: InStatement[], _mode?: "write" | "read" | "deferred"): Promise<ResultSet[]> {
    const prepared = stmts.map((s) => this.prepare(s));
    const results = await this.db().batch<Record<string, unknown>>(prepared.map((p) => p.prepared));
    return Promise.all(results.map((r, i) => this.shape(prepared[i].sql, prepared[i].prepared, r)));
  }
}

export const sqlite = new D1Sqlite(() => (env as unknown as { DB: D1Database }).DB);
